import random


def kth_smallest(nums, k):
    a = list(nums)
    lo, hi, want = 0, len(a) - 1, k - 1
    while True:
        p = random.randint(lo, hi)
        a[p], a[hi] = a[hi], a[p]
        store = lo
        for i in range(lo, hi):
            if a[i] < a[hi]:
                a[i], a[store] = a[store], a[i]
                store += 1
        a[store], a[hi] = a[hi], a[store]
        if store == want:
            return a[store]
        if store < want:
            lo = store + 1
        else:
            hi = store - 1

