static final Random RNG = new Random(7);

static void swap(int[] a, int i, int j) {
    int t = a[i]; a[i] = a[j]; a[j] = t;
}

static int kthSmallest(int[] nums, int k) {
    int[] a = nums.clone();
    int lo = 0, hi = a.length - 1, want = k - 1;
    while (true) {
        swap(a, lo + RNG.nextInt(hi - lo + 1), hi);
        int store = lo;
        for (int i = lo; i < hi; i++)
            if (a[i] < a[hi]) swap(a, i, store++);
        swap(a, store, hi);
        if (store == want) return a[store];
        if (store < want) lo = store + 1;
        else hi = store - 1;
    }
}

