}

int kthSmallest(const int* nums, int n, int k) {
    int* a = malloc(n * sizeof(int));
    memcpy(a, nums, n * sizeof(int));
    int lo = 0, hi = n - 1, want = k - 1;
    while (true) {
        swap(a, lo + rand() % (hi - lo + 1), hi);
        int store = lo;
        for (int i = lo; i < hi; i++)
            if (a[i] < a[hi]) swap(a, i, store++);
        swap(a, store, hi);
        if (store == want) {
            int answer = a[store];
            free(a);
            return answer;
        }
        if (store < want) lo = store + 1;
        else hi = store - 1;
    }
}

